p=plan['\\''propositions'\\''][0];target=pr['\\''approvals'\\'']['\\''P1'\\'']['\\''contract_hash'\\'']
found=[]
for k in range(1,len(p)+1):
 for keys in itertools.combinations(p,k):
  obj={z:p[z] for z in keys}
  for sort,ensure,indent,sep,nl in itertools.product([True,False],[True,False],[None,2],[None,('\\'','\\'','\\'':'\\'')],['\\'''\\'','\\''\\n'\\'']):
